# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KESİRLERLE DÖRT İŞLEM PROBLEMLERİ VE MODEL TEMSİLİ (MAT.6.1.7)</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Bütünün Kesir Kadarını Bulma (Çarpma)</text>\n  <text x="36" y="96" font-size="11.5" fill="#1e3a8a">• Verilen bütün, kesir ile çarpılır.</text>\n  <text x="36" y="118" font-size="11.5" fill="#1e3a8a">• Örnek: 120 sayfalık eserin 5\'te 3\'ü kaç sayfadır?</text>\n  <rect x="36" y="132" width="48" height="24" fill="#3b82f6" stroke="#1d4ed8"/>\n  <rect x="84" y="132" width="48" height="24" fill="#3b82f6" stroke="#1d4ed8"/>\n  <rect x="132" y="132" width="48" height="24" fill="#3b82f6" stroke="#1d4ed8"/>\n  <rect x="180" y="132" width="48" height="24" fill="#dbeafe" stroke="#1d4ed8"/>\n  <rect x="228" y="132" width="48" height="24" fill="#dbeafe" stroke="#1d4ed8"/>\n  <text x="60" y="148" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">24</text>\n  <text x="108" y="148" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">24</text>\n  <text x="156" y="148" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">24</text>\n  <text x="204" y="148" text-anchor="middle" font-size="10" fill="#1e3a8a">24</text>\n  <text x="252" y="148" text-anchor="middle" font-size="10" fill="#1e3a8a">24</text>\n  <text x="36" y="180" font-size="11.5" font-weight="bold" fill="#1e40af">1 parça: 120 ÷ 5 = 24 sayfa</text>\n  <text x="36" y="202" font-size="11.5" font-weight="bold" fill="#1e40af">3 parça: 24 × 3 = 72 sayfa (Kalan: 48 sayfa)</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kesir Kadarı Verilen Bütünü Bulma (Bölme)</text>\n  <text x="376" y="96" font-size="11.5" fill="#14532d">• Verilen parça, kesre bölünür (birim kesir bulunur).</text>\n  <text x="376" y="118" font-size="11.5" fill="#14532d">• Örnek: 7\'de 4\'ü 60 L olan deponun tamamı kaç L\'dir?</text>\n  <rect x="376" y="132" width="36" height="24" fill="#22c55e" stroke="#15803d"/>\n  <rect x="412" y="132" width="36" height="24" fill="#22c55e" stroke="#15803d"/>\n  <rect x="448" y="132" width="36" height="24" fill="#22c55e" stroke="#15803d"/>\n  <rect x="484" y="132" width="36" height="24" fill="#22c55e" stroke="#15803d"/>\n  <rect x="520" y="132" width="36" height="24" fill="#dcfce7" stroke="#15803d"/>\n  <rect x="556" y="132" width="36" height="24" fill="#dcfce7" stroke="#15803d"/>\n  <rect x="592" y="132" width="36" height="24" fill="#dcfce7" stroke="#15803d"/>\n  <text x="448" y="148" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">4 parça = 60 L</text>\n  <text x="376" y="180" font-size="11.5" font-weight="bold" fill="#166534">1 parça (birim kesir): 60 ÷ 4 = 15 L</text>\n  <text x="376" y="202" font-size="11.5" font-weight="bold" fill="#166534">Tamamı (7 parça): 15 × 7 = 105 L</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ONDALIK GÖSTERİM VE YÜZDE İÇEREN PROBLEMLER (MAT.6.1.7)</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Temsiller Arası Eş Değerlik</text>\n  <text x="40" y="100" font-size="11.5" fill="#831843">• Yüzde 25 (%25) = 0,25 = Çeyrek (4\'te 1)</text>\n  <text x="40" y="124" font-size="11.5" fill="#831843">• Yüzde 50 (%50) = 0,5 = Yarım (2\'de 1)</text>\n  <text x="40" y="148" font-size="11.5" fill="#831843">• Yüzde 75 (%75) = 0,75 = Dörtte üç (4\'te 3)</text>\n  <text x="40" y="172" font-size="11.5" fill="#831843">• Yüzde 20 (%20) = 0,2 = Beşte bir (5\'te 1)</text>\n  <text x="40" y="198" font-size="11" font-weight="bold" fill="#9d174d">Problemde en kolay işlem yapılan temsil seçilir!</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İndirim, Zam ve Alışveriş Problemleri</text>\n  <text x="375" y="98" font-size="11.5" fill="#713f12">• Örnek: 800 TL\'lik mont %25 indirimle satılıyor.</text>\n  <text x="375" y="120" font-size="11.5" fill="#713f12">  İndirim tutarı: 800 × 0,25 = 200 TL</text>\n  <text x="375" y="142" font-size="11.5" font-weight="bold" fill="#854d0e">  İndirimli satış fiyatı: 800 − 200 = 600 TL</text>\n  <text x="375" y="168" font-size="11.5" fill="#713f12">• Ondalık Birim Fiyat: Kilosu 42,5 TL olan</text>\n  <text x="375" y="188" font-size="11.5" fill="#713f12">  cevizden 2,4 kg alan kişi:</text>\n  <text x="375" y="210" font-size="11.5" font-weight="bold" fill="#854d0e">  42,5 × 2,4 = 102 TL öder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STANDART UZUNLUK ÖLÇME BİRİMLERİ BASAMAKLARI (MAT.6.1.8)</text>\n  <rect x="25" y="46" width="650" height="196" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <rect x="45" y="64" width="76" height="32" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="83" y="85" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">km</text>\n  <rect x="130" y="82" width="76" height="32" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="168" y="103" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">hm</text>\n  <rect x="215" y="100" width="76" height="32" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="253" y="121" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">dam</text>\n  <rect x="300" y="118" width="84" height="36" rx="6" fill="#fef08a" stroke="#ca8a04" stroke-width="2"/>\n  <text x="342" y="141" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">m (Metre)</text>\n  <rect x="393" y="138" width="76" height="32" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="431" y="159" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">dm</text>\n  <rect x="478" y="156" width="76" height="32" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="516" y="177" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">cm</text>\n  <rect x="563" y="174" width="76" height="32" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="601" y="195" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">mm</text>\n\n  <text x="490" y="84" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Aşağı İnerken: Her basamakta × 10</text>\n  <text x="490" y="104" text-anchor="middle" font-size="11" fill="#1e3a8a">(1 km = 1000 m · 1 m = 100 cm = 1000 mm)</text>\n  <text x="195" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Yukarı Çıkarken: Her basamakta ÷ 10</text>\n  <text x="195" y="198" text-anchor="middle" font-size="11" fill="#14532d">(250 cm = 2,5 m · 3400 m = 3,4 km)</text>\n  <text x="350" y="228" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">Temel Ölçüt Birim: Metre (m) · Üst Katlar: km, hm, dam · Alt Katlar: dm, cm, mm</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
